const csv = $input.item.json.data;
const lines = csv.split('\n').filter(l => l.trim());
const headers = lines[0].split(',').map(h => h.replace(/"/g, '').trim());

// Parse all rows
const rows = [];
for (let i = 1; i < lines.length; i++) {
  const values = [];
  let current = '';
  let inQuotes = false;
  for (const char of lines[i]) {
    if (char === '"') { inQuotes = !inQuotes; }
    else if (char === ',' && !inQuotes) { values.push(current.trim()); current = ''; }
    else { current += char; }
  }
  values.push(current.trim());
  if (values.length >= headers.length) {
    const row = {};
    headers.forEach((h, idx) => row[h] = values[idx] || '');
    rows.push(row);
  }
}

// ✅ FIX 1: Parse "DD/MM/YYYY HH:MM:SS" or "DD/MM/YYYY" into a real Date
const parseDateTime = (str) => {
  const [datePart, timePart = '00:00:00'] = (str || '').trim().split(' ');
  const [d, m, y] = datePart.split('/');
  return new Date(`${y}-${m}-${d}T${timePart}`);
};

// Get today's date in DD/MM/YYYY
const now = new Date();
const today = `${String(now.getDate()).padStart(2,'0')}/${String(now.getMonth()+1).padStart(2,'0')}/${now.getFullYear()}`;

// ✅ FIX 1: Filter by date portion only (handles datetime values in date column)
const todayRows = rows.filter(r => (r.date || '').trim().substring(0, 10) === today);

// ✅ FIX 1 + FIX 2: Sort today's rows by full datetime before calculating balances
const sortedToday = [...todayRows].sort((a, b) => parseDateTime(a.date) - parseDateTime(b.date));

// ✅ FIX 3: Explicit credit/debit check — unknown types are ignored, not misclassified
let totalCredit = 0, totalDebit = 0, creditCount = 0, debitCount = 0;
sortedToday.forEach(r => {
  const amt = parseFloat(r.amount) || 0;
  const type = (r.alert_type || '').toLowerCase();
  if (type === 'credit') { totalCredit += amt; creditCount++; }
  else if (type === 'debit') { totalDebit += amt; debitCount++; }
});

// ✅ FIX 2: Opening balance — prior rows sorted by datetime, pick the last one
const priorRows = rows.filter(r => (r.date || '').trim().substring(0, 10) < today);
const sortedPrior = [...priorRows].sort((a, b) => parseDateTime(a.date) - parseDateTime(b.date));
const openingBalance = sortedPrior.length > 0
  ? parseFloat(sortedPrior[sortedPrior.length - 1].closing_balance) || 0
  : 0;

// ✅ FIX 2: Closing balance — last row of today after datetime sort
const closingBalance = sortedToday.length > 0
  ? parseFloat(sortedToday[sortedToday.length - 1].closing_balance) || 0
  : 0;

const fmt = (n) => '₦' + parseFloat(n).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// Build full HTML
const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; color: #1e293b; padding: 40px; }
  h1 { font-size: 24px; margin-bottom: 4px; }
  .subtitle { color: #64748b; font-size: 13px; margin-bottom: 32px; }
  .cards { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 32px; }
  .card { border-radius: 12px; padding: 20px 24px; background: #f8fafc; border: 1px solid #e2e8f0; }
  .card-label { font-size: 11px; text-transform: uppercase; color: #94a3b8; letter-spacing: 0.5px; margin-bottom: 8px; }
  .card-value { font-size: 26px; font-weight: 700; color: #1e293b; }
  .card-meta { font-size: 12px; color: #94a3b8; margin-top: 6px; }
  .card.debit .card-value { color: #ef4444; }
  .card.credit .card-value { color: #10b981; }
