  .net-flow span { font-weight: 700; }
  .footer { margin-top: 40px; font-size: 11px; color: #94a3b8; text-align: center; border-top: 1px solid #e2e8f0; padding-top: 16px; }
</style>
</head>
<body>
  <h1>📊 Daily Transaction Summary</h1>
  <p class="subtitle">Date: ${today} &nbsp;|&nbsp; Generated at 7:00 PM</p>
  <div class="cards">
    <div class="card">
      <div class="card-label">Opening Balance</div>
      <div class="card-value">${fmt(openingBalance)}</div>
    </div>
    <div class="card debit">
      <div class="card-label">Total Debit</div>
      <div class="card-value">${fmt(totalDebit)}</div>
      <div class="card-meta">${debitCount} transaction${debitCount !== 1 ? 's' : ''}</div>
    </div>
    <div class="card credit">
      <div class="card-label">Total Credit</div>
      <div class="card-value">${fmt(totalCredit)}</div>
      <div class="card-meta">${creditCount} transaction${creditCount !== 1 ? 's' : ''}</div>
    </div>
    <div class="card">
      <div class="card-label">Closing Balance</div>
      <div class="card-value">${fmt(closingBalance)}</div>
    </div>
  </div>
  <div class="net-flow">
    Net Flow: <span style="color: ${(totalCredit - totalDebit) >= 0 ? '#10b981' : '#ef4444'}">${fmt(totalCredit - totalDebit)}</span>
    &nbsp;&nbsp;|&nbsp;&nbsp; Total Transactions: <span>${sortedToday.length}</span>
  </div>
  <div class="footer">This is an automated daily report. Do not reply to this email.</div>
</body>
