const creditMatch = keyRaw.match(/Credit\s*:\s*[A-Z]*([0-9,]+(?:\.[0-9]{1,2})?)/i);

let alertType = "N/A";
let amount = "N/A";

if (debitMatch) {
  alertType = "Debit";
  amount = debitMatch[1].replace(/,/g, '');
} else if (creditMatch) {
  alertType = "Credit";
  amount = creditMatch[1].replace(/,/g, '');
}

