const dateMatch = keyRaw.match(/Date\s*:\s*(\d{2}\/\d{2}\/\d{4})\s+(\d{1,2}:\d{2}\s*[APM]{2})/i);
let datetime = "N/A";
if (dateMatch) {
  datetime = `${dateMatch[1]} ${dateMatch[2].trim()}`;
} else if (timeRaw) {
  datetime = timeRaw;
}

// Extract balance
const balMatch = keyRaw.match(/Bal\s*:\s*[A-Z]*([0-9,]+(?:\.[0-9]{1,2})?)/i);
const balance = balMatch ? balMatch[1].replace(/,/g, '') : "N/A";

return {
  json: {
    sender,
    account,
    alertType,
    amount,
    description,
    ref,
    datetime,
    balance
  }
};

