// DateTime parser: handles "DD/MM/YYYY HH:MM AM/PM" or plain "DD/MM/YYYY"
function parseDateTime(str) {
  if (!str) return new Date(0);
  const parts = str.trim().split(' ');
  const [d, m, y] = parts[0].split('/').map(Number);
  let hours = 0, minutes = 0;
  if (parts[1]) {
