    hours = h;
    minutes = min;
    const meridiem = (parts[2] || '').toUpperCase();
    if (meridiem === 'PM' && hours !== 12) hours += 12;
    if (meridiem === 'AM' && hours === 12) hours = 0;
  }
  return new Date(y, m - 1, d, hours, minutes);
}

function getDayKey(dateStr) {
  return dateStr.trim().split(' ')[0]; // "DD/MM/YYYY"
}

// Normalize rows
const allTx = rows.map(r => ({
  date:    r.date || '',
  type:    (r.alert_type || '').toLowerCase().trim(),
  amount:  parseFloat(r.amount) || 0,
  balance: parseFloat(r.balance) || 0,
  description: r.description || '',
  reference:   r.reference || ''
})).sort((a, b) => parseDateTime(a.date) - parseDateTime(b.date));

// ── Seed balance: back-calculate from table_5 first transaction ever ──
const firstTx = allTx[0];
let seedBalance = 0;
if (firstTx) {
  seedBalance = firstTx.type === 'debit'
    ? firstTx.balance + firstTx.amount
    : firstTx.balance - firstTx.amount;
}

// Group all transactions by day
const dayMap = {};
allTx.forEach(tx => {
  const day = getDayKey(tx.date);
  if (!dayMap[day]) dayMap[day] = [];
  dayMap[day].push(tx);
});

// Sort unique days ascending
const allDays = Object.keys(dayMap).sort((a, b) => {
  const [da, ma, ya] = a.split('/').map(Number);
  const [db, mb, yb] = b.split('/').map(Number);
  return new Date(ya, ma-1, da) - new Date(yb, mb-1, db);
});

// Chain: opening → closing per day
// Closing = last transaction's bank balance (col F) sorted by datetime
const dayBalances = {};
let runningBalance = seedBalance;
allDays.forEach(day => {
  const dayTxs = [...dayMap[day]].sort((a, b) => parseDateTime(a.date) - parseDateTime(b.date));
  const dayClose = dayTxs[dayTxs.length - 1].balance;
  dayBalances[day] = { opening: runningBalance, closing: dayClose };
  runningBalance = dayClose;
});

