const todayKey = `${String(now.getDate()).padStart(2,'0')}/${String(now.getMonth()+1).padStart(2,'0')}/${now.getFullYear()}`;
const todayStr = todayKey;

const todayTxs = (dayMap[todayKey] || []).sort((a, b) => parseDateTime(a.date) - parseDateTime(b.date));

let totalCredit = 0, totalDebit = 0, creditCount = 0, debitCount = 0;
todayTxs.forEach(r => {
  if (r.type === 'credit') { totalCredit += r.amount; creditCount++; }
  else if (r.type === 'debit') { totalDebit += r.amount; debitCount++; }
});

// Opening = previous day's closing, or seed if today is first day
const daysBeforeToday = allDays.filter(d => {
  const [dd, dm, dy] = d.split('/').map(Number);
  return new Date(dy, dm-1, dd) < new Date(now.getFullYear(), now.getMonth(), now.getDate());
});
const openingBalance = daysBeforeToday.length > 0
  ? dayBalances[daysBeforeToday[daysBeforeToday.length - 1]].closing
  : seedBalance;

// Closing = last transaction's balance today, or opening if no transactions
const closingBalance = todayTxs.length > 0
  ? todayTxs[todayTxs.length - 1].balance
  : openingBalance;

